import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    for i, w in enumerate(words):
        ans = -1
        for k in range(1, len(w) + 1):
            p = w[:k]
            shared = False
            for j, v in enumerate(words):
                if j != i and v[:k] == p:
                    shared = True
                    break
            if not shared:
                ans = k
                break
        print(ans)


main()
